// ブロックを読み上げ用のプレーンテキストにする。助手の音声・要約や検索でそのまま使える。
// t:'data' は実データから作るので、ここでは中身を持たない(画面側で差し込む)
const helpBlockPlainText = (block) => {
  if (!block) return '';
  if (block.t === 'kv') return (block.rows || []).map(row => `${row[0]}: ${row[1]}`).join('\n');
  if (block.t === 'list' || block.t === 'steps') return (block.items || []).join('\n');
  if (block.t === 'note') return [block.title, block.text].filter(Boolean).join(': ');
  if (block.t === 'data') return '';
  return block.text || '';
};
const helpPlainText = (topic) => [topic?.title, ...(topic?.blocks || []).map(helpBlockPlainText)].filter(Boolean).join('\n');
const helpFindCategory = (categoryId) => HELP_CATEGORIES.find(c => c.id === categoryId) || null;
const helpFindTopic = (categoryId, topicId) => (helpFindCategory(categoryId)?.topics || []).find(t => t.id === topicId) || null;
